import 'package:flutter/material.dart';
class SecretMemoScreen extends StatefulWidget { const SecretMemoScreen({super.key}); @override State<SecretMemoScreen> createState() => _SecretMemoScreenState(); }
class _SecretMemoScreenState extends State<SecretMemoScreen> {
  final _memos = ['지은 님이 마음에 들어요. 누구보다 편안하고 말이 잘 통했어요.'];
